insert into public.study_materials
select * from jsonb_populate_record(null::public.study_materials, '{"id":"850c316d-0878-43d2-b75d-ebbd75c2b005","quiz":[{"a":true,"q":"Na teoria tripartida apresentada na apostila, crime é composto por fato típico, ilicitude e culpabilidade.","why":"Correto. A apostila usa a concepção tripartida como referência majoritária e organiza a análise nesses três substratos."},{"a":false,"q":"Pelo finalismo descrito na apostila, dolo e culpa são elementos da culpabilidade.","why":"Errado. A apostila explica que dolo e culpa foram deslocados para a conduta, dentro do fato típico."},{"a":false,"q":"A cogitação, por si só, é punível como tentativa quando a intenção criminosa está comprovada.","why":"Errado. A cogitação é fase interna e impunível; a tentativa exige início da execução."},{"a":true,"q":"Há tentativa quando o agente inicia a execução, mas não consuma o crime por circunstâncias alheias à sua vontade.","why":"Correto. É a definição do art. 14, II, do CP reproduzida na apostila."},{"a":true,"q":"Na desistência voluntária, o agente interrompe a execução mesmo podendo prosseguir; no arrependimento eficaz, impede o resultado depois de esgotar os meios executórios.","why":"Correto. Essa é a distinção prática destacada na Aula 10 e associada ao art. 15 do CP."},{"a":false,"q":"O arrependimento posterior ocorre antes da consumação do crime.","why":"Errado. A apostila o situa depois da consumação, nos crimes sem violência ou grave ameaça, observados os requisitos do art. 16."},{"a":true,"q":"O art. 23 do CP lista estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito.","why":"Correto. São as quatro causas de exclusão da ilicitude enumeradas na Aula 11."},{"a":false,"q":"A legítima defesa autoriza reação contra agressão passada ou contra perigo futuro meramente incerto.","why":"Errado. A apostila exige agressão injusta atual ou iminente; agressão passada caracteriza vingança, e a futura incerta não autoriza reação."},{"a":true,"q":"Na teoria normativa pura, a culpabilidade tem como elementos imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa.","why":"Correto. São os três elementos listados na Aula 12."},{"a":false,"q":"A embriaguez voluntária ou culposa exclui a culpabilidade quando completa.","why":"Errado. A apostila afirma que não exclui a imputabilidade, conforme o art. 28 do CP."},{"a":true,"q":"O erro de tipo essencial sempre exclui o dolo; se inevitável, exclui também a culpa.","why":"Correto. Essa é a distinção da Aula 13: se evitável, pode haver responsabilização culposa quando prevista."},{"a":false,"q":"O Código Penal adota como regra a teoria pluralista no concurso de pessoas.","why":"Errado. A apostila apresenta a teoria monista ou unitária, em forma temperada, como regra do art. 29 do CP."}],"slug":"ufac-2026-direito-penal-i-aulas-9-14","title":"Direito Penal I — Aulas 9 a 14 (UFAC 2026.2)","body_md":"Apostila de Direito Penal – Aulas 9 a 14\n\nApostila de Direito Penal – Aulas 9 a 14\n  Nov 12, 2026        ·   @Shelen\n\nEsta apostila explica com calma, em linguagem simples e com exemplos, tudo o que a\nprova cobra: tipicidade, dolo e culpa (aula 9), iter criminis e crime impossível (aula 10),\nilicitude (aula 11), culpabilidade (aula 12), teoria do erro (aula 13) e concurso de pessoas\n(aula 14). Os artigos citados são do Código Penal. Se a professora usar um autor\nespecífico, confira nos slides o nome das teorias; as ideias são as mesmas.\n\n\nComo pensar um crime (o mapa de tudo)\nPela teoria majoritária (tripartida), crime = fato típico + ilícito + culpável. Na prova, quase\ntoda questão se resolve passando por essas três camadas, em ordem:\n\n   1. Fato típico? O que a pessoa fez se encaixa na descrição de um crime (conduta,\n      resultado, nexo causal e tipicidade)? Se não, o fato é atípico e acabou. (Aulas 9 e 10.)\n   2. É ilícito? Existe alguma situação que autoriza o fato, como legítima defesa ou estado\n      de necessidade? Se sim, não há crime. (Aula 11.)\n   3. O autor é culpável? Ele era capaz, podia saber que era proibido e dele se podia exigir\n      outra conduta? Se não, o crime existe, mas ele fica isento de pena. (Aulas 12 e 13.)\n\nA aula 14 (concurso de pessoas) cuida de quando várias pessoas participam do mesmo\ncrime.\n\nUma corrente minoritária (bipartida) diz que a culpabilidade não faz parte do crime, mas é\npressuposto para aplicar a pena. Na prática, isso quase nunca muda a resposta.\n\n\nAula 9 – Tipicidade, dolo e culpa\n\nTipo penal e tipicidade\nTipo penal é a descrição que a lei faz de uma conduta proibida. Exemplo: “matar alguém”\n(art. 121). Tipicidade é o encaixe entre o que a pessoa realmente fez e essa descrição. Se\nalguém mata outra pessoa, o fato é típico do art. 121; se apenas xinga, não é.\n\nNo esquema clássico, o fato típico é analisado por conduta, resultado naturalístico (quando exigido pelo tipo), nexo causal (nos crimes materiais) e tipicidade. Crimes formais e de mera conduta não exigem resultado naturalístico para a consumação.\n\n       Conduta: ação ou omissão humana, voluntária e consciente, voltada a uma finalidade.\n       A doutrina majoritária lê a Parte Geral do CP sob a teoria finalista: dolo e culpa são analisados no fato típico, integrando a conduta, e não como elementos da culpabilidade.\n       Resultado: a modificação no mundo causada pela conduta (a morte, a perda do objeto\n       etc.).\n\n                                                                                         Page 1 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n       Nexo causal: a ligação entre a conduta e o resultado (art. 13: causa é a ação ou\n       omissão sem a qual o resultado não teria ocorrido).\n       Tipicidade formal e material: formal é o encaixe na lei; material é a lesão relevante ao\n       bem jurídico protegido. Por isso o princípio da insignificância pode afastar a tipicidade\n       material: o furto de algo de valor mínimo, por exemplo, pode ser tratado como fato\n       atípico.\n\nPrincípio da insignificância (tipicidade material), segundo os slides. Para o STF, o fato só\né insignificante se estiverem presentes, ao mesmo tempo, os quatro vetores: mínima\nofensividade da conduta, ausência de periculosidade social, reduzidíssimo grau de\nreprovabilidade e inexpressividade da lesão jurídica (HC 84.412/SP).\n\n\n   Situação                                                     Regra\n\n   Crimes com violência ou grave ameaça (ex.:                   Não cabe\n   roubo)\n\n   Crimes de perigo abstrato ou que protegem                    Em regra, não cabe\n   a segurança pública (ex.: porte ilegal de\n   arma)\n\n   Reincidência e habitualidade criminosa                       Em regra impedem, salvo\n                                                                desproporcionalidade manifesta\n\n   Bens personalíssimos e indisponíveis (vida,                  Não cabe\n   integridade física grave)\n\n   Crimes patrimoniais (critério do STJ)                        O STJ utiliza o patamar de 10% como referência em alguns julgados, não como limite automático; avaliam-se também os quatro vetores e as circunstâncias concretas.\n\n   Crimes contra a Administração Pública                        Em regra, não se aplica (Súmula 599/STJ), ressalvadas distinções jurisprudenciais em casos concretos.\n\n   Violência doméstica contra a mulher                          Em regra, não se aplica (Súmula 589/STJ).\n\n   Descaminho (tributo iludido)                                 Admite, quando o tributo não passa de R$\n                                                                20.000,00 (teto das execuções fiscais)\n\n\nBagatela própria x bagatela imprópria\n\n\n                                   Bagatela própria (insignificância)   Bagatela imprópria (irrelevância\n                                                                        penal do fato)\n\n   Origem                          Roxin (proteção subsidiária de       Luiz Flávio Gomes (desnecessidade\n                                   bens jurídicos)                      da pena)\n\n                                                                                                           Page 2 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n                                   Bagatela própria (insignificância)      Bagatela imprópria (irrelevância\n                                                                           penal do fato)\n\n   Natureza                        Exclui a tipicidade material: o fato    O crime existe, mas a pena é\n                                   é atípico                               desnecessária segundo construção doutrinária controvertida; não há causa geral automática de extinção da punibilidade ou dispensa da pena.\n\n   Quando se                       Na conduta, no momento do fato          Depois do fato, no processo ou na\n   analisa                                                                 sentença\n\n   O que pesa                      Os quatro vetores do STF                Fatores posteriores ao crime:\n                                                                           reparação do dano, colaboração,\n                                                                           primariedade, conciliação\n\n   Base                            Art. 1º do CP e Constituição            Art. 59 do CP (pena “necessária e\n                                   (ultima ratio)                          suficiente”) e não cria, por si só, perdão judicial ou causa de extinção da punibilidade.\n\n   Absolvição                      Art. 386, III, do CPP (atipicidade)     Não há absolvição ou extinção automática; exige hipótese legal específica.\n\n\nTipicidade conglobante (Zaffaroni). O ordenamento jurídico é uno: o Estado não pode\nproibir no Direito Penal o que ele mesmo ordena ou incentiva em outro ramo do Direito.\nExemplo: o cirurgião que corta o paciente. Formalmente é lesão corporal, mas é um ato\nfomentado pelo Estado (direito à saúde); logo, é atípico.\n\n\n                                                     Sistema tradicional       Teoria conglobante (Zaffaroni)\n                                                     (Código Penal)\n\n   Fórmula da tipicidade                             Formal + Material         Formal + Conglobante\n                                                                               (antinormatividade + tipicidade\n                                                                               material)\n\n   Antinormatividade                                 Fica na ilicitude         É exigência da própria\n                                                     (segundo degrau)          tipicidade: a conduta não pode\n                                                                               ser ordenada nem incentivada\n                                                                               pelo Estado\n\n   Estrito cumprimento do dever                      Excludente de             Causa de atipicidade\n   legal                                             ilicitude\n\n   Exercício regular de direito                      Excludente de             Atipicidade\n   fomentado (ex.: cirurgia)                         ilicitude\n\n   Exercício regular meramente                       Excludente de             Continua na ilicitude\n   tolerado (ex.: trote acadêmico                    ilicitude\n   moderado)\n\n                                                                                                              Page 3 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n                                           Sistema tradicional    Teoria conglobante (Zaffaroni)\n                                           (Código Penal)\n\n   Absolvição                              Art. 386, VI, do CPP   Art. 386, III, do CPP\n\n\nO CP adota formalmente o modelo tradicional (clássico-finalista), mas a tese de Zaffaroni\né muito cobrada como forma de conter o tipo penal.\n\nEsclarecimentos da professora sobre a tipicidade (conversa de 12/11)\n\n       As espécies de tipicidade funcionam como etapas sucessivas (filtros): só se avança\n       para a seguinte se o fato passou pela anterior. Pela teoria tradicional, a tipicidade é\n       formal + material, e o que for ordenado ou permitido por outra lei é resolvido depois,\n       na ilicitude (art. 23, III). Pela teoria conglobante, há um terceiro filtro dentro da própria\n       tipicidade: a antinormatividade. Assim, o que outra lei ordena ou incentiva nem chega\n       a ser típico.\n       Se falta a tipicidade material (ex.: insignificância), o fato é atípico e não é crime.\n       Onde a conglobante é usada no Brasil (segundo a professora): atos de agentes\n       públicos (oficial de justiça que penhora, policial que faz prisão legal); atividades\n       fomentadas pelo Estado (esportes regulados, como MMA e futebol dentro das regras,\n       e cirurgias feitas conforme a técnica); práticas culturais ou religiosas protegidas pela\n       Constituição (uso ritual de ayahuasca, práticas tradicionais indígenas). A ideia central\n       é: sempre que punir pelo Código Penal criaria a contradição de criminalizar algo que a\n       Constituição, outra lei ou o Estado autorizou, ordenou ou incentivou.\n       Arrombar a porta para cumprir mandado é exemplo clássico de estrito cumprimento\n       do dever legal (art. 293 do CPP: se o morador resiste ou não atende, durante o dia).\n       Pela conglobante, o fato é atípico (não há antinormatividade, porque a lei processual\n       mandou fazer). Pela tradicional, o fato é típico (dano, art. 163, e violação de domicílio,\n       art. 150) e o crime é excluído na ilicitude. Nas duas teorias, o agente só está amparado\n       se agir dentro dos limites da ordem e com proporcionalidade (de dia, arrombando só o\n       necessário depois da recusa). Excesso injustificado gera responsabilidade por abuso.\n       Insignificância não é o mesmo que contradição conglobante. No furto insignificante,\n       o Estado não está permitindo o furto: o ato continua proibido pelo ordenamento (é um\n       ilícito civil, e a pessoa pode ter de devolver o bem ou indenizar), mas o Direito Penal\n       não age por causa da intervenção mínima. Na contradição conglobante, é uma lei que\n       manda ou incentiva a conduta (penhora, luta dentro das regras) e o Código Penal\n       tentaria puni-la.\n\n                                                                                                Page 4 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nDolo (art. 18, I)\nCrime doloso é aquele em que o agente quis o resultado ou assumiu o risco de produzi-lo.\nO dolo tem dois componentes: consciência (sabe o que faz) e vontade (quer ou aceita o\nresultado).\n\n\n   Espécie                                 O que é                          Exemplo\n\n   Dolo direto de 1º grau                  O agente quer exatamente         Atira na vítima para matá-la\n                                           o resultado\n\n   Dolo direto de 2º grau                  Não quer o resultado             Para matar o alvo, explode o\n   (consequências necessárias)             paralelo, mas sabe que ele é     carro, sabendo que o\n                                           certo por causa do meio          motorista também morrerá\n                                           escolhido\n\n   Dolo eventual                           Prevê o resultado como           Dirige em altíssima\n                                           possível e aceita o risco: “se   velocidade em rua cheia,\n                                           acontecer, aconteceu”            sem se importar se\n                                                                            atropelar alguém\n\n\nNo dolo eventual vale a teoria do assentimento: o agente concorda com o risco de\nproduzir o resultado.\n\n\nCulpa (art. 18, II)\nCrime culposo é aquele em que o agente deu causa ao resultado por imprudência,\nnegligência ou imperícia, isto é, quebrando o dever de cuidado que se espera de uma\npessoa comum, sem querer o resultado.\n\n       Imprudência: agir de forma perigosa (ação). Ex.: furar o sinal vermelho.\n       Negligência: deixar de tomar o cuidado devido (omissão). Ex.: deixar arma carregada\n       ao alcance de criança.\n       Imperícia: falta de técnica no exercício de profissão, arte ou ofício. Ex.: médico que faz\n       um procedimento sem a técnica exigida.\n\nElementos do crime culposo: conduta voluntária, quebra do dever objetivo de cuidado,\nresultado involuntário, previsibilidade objetiva do resultado e tipicidade. Atenção: só\nexiste crime culposo quando a lei prevê expressamente (art. 18, parágrafo único). Sem\nprevisão, só se pune a forma dolosa.\n\nDetalhes da estrutura do crime culposo (slides): o desvalor está no modo defeituoso de\nexecutar, não na finalidade do agente, que pode ser lícita. O nexo causal usa a teoria da\nequivalência (art. 13) somada à imputação objetiva: o agente criou ou aumentou um risco\nproibido. A previsibilidade objetiva é a de uma pessoa prudente (não confunda com a\n\n                                                                                                  Page 5 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nprevisibilidade subjetiva, que é questão de culpabilidade). Se o resultado era imprevisível,\né caso fortuito ou força maior e o fato é atípico. Também são atípicos: o ato reflexo ou a\ncoação física (falta conduta) e o resultado dentro do risco permitido. Crime culposo não\nadmite tentativa, salvo na culpa imprópria. Se o fato culposo não está previsto em lei, a\nquestão fica só na responsabilidade civil.\n\nCulpa consciente e inconsciente\n\n       Culpa inconsciente: o agente não previu o resultado, embora ele fosse previsível.\n       Culpa consciente: o agente previu o resultado, mas acreditou sinceramente que ele\n       não aconteceria, confiando na sua habilidade ou na sorte.\n\nA pegadinha clássica: dolo eventual x culpa consciente. Nos dois, o agente prevê o\nresultado. A diferença está na atitude diante dele:\n\n\n                                      Dolo eventual                  Culpa consciente\n\n   Prevê o                            Sim                            Sim\n   resultado?\n\n   Atitude                            Aceita o risco; tanto faz se   Acredita que não vai acontecer e confia\n                                      acontecer                      em evitá-lo\n\n   Responde por                       Crime doloso                   Crime culposo\n\n\nNo trânsito (STF e STJ, segundo os slides). Embriaguez ou racha, por si só, não permitem\npresumir dolo eventual (STF, HC 101.698/RJ). O STJ exige circunstâncias anormais e\nconcretas que mostrem total desprezo pela vida alheia. Álcool e excesso de velocidade são dados relevantes, mas não autorizam presunção automática de dolo eventual nem de culpa consciente. A classificação depende das circunstâncias concretas e da prova sobre a atitude do agente diante do risco. Por isso o\nracha com morte culposa tem tipo próprio no art. 308, §2º, do CTB (dolo no racha, culpa na\nmorte). O dolo eventual fica para os casos em que o dolo é demonstrado, e vai ao Tribunal\ndo Júri; a culpa vai à vara criminal comum. Na dúvida intransponível entre dolo eventual e\nculpa consciente, prevalece a opção menos grave (in dubio pro reo): culpa consciente.\n\nOutros pontos que costumam cair:\n\n       Não existe “compensação de culpas” no Direito Penal: se a vítima também foi\n       imprudente, isso não elimina a culpa do agente (pode apenas influenciar a pena).\n       Crime preterdoloso (art. 19): há dolo na conduta antecedente e culpa no resultado\n       mais grave. Ex.: lesão corporal seguida de morte (art. 129, §3º): quis ferir, não quis\n       matar, mas a morte era previsível.\n       O art. 19 também proíbe a responsabilidade penal objetiva: o resultado que agrava a\n       pena só pode ser atribuído ao agente se ele o causou ao menos culposamente.\n\n                                                                                                       Page 6 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nReforço sobre o preterdolo (slides): a regra é “dolo no antecedente, culpa no\nconsequente”. O agente quer um resultado menor (minus) e causa, sem querer, um\nresultado maior (majus) que era previsível. Ele não responde por homicídio doloso, nem\npor homicídio simplesmente culposo, e sim pela lesão corporal seguida de morte (art. 129,\n§3º). Se o resultado mais grave fosse imprevisível (caso fortuito), ele responderia só pela\nconduta dolosa inicial (lesão corporal comum). Está vedada a responsabilidade sem dolo\nou culpa (versari in re illicita).\n\n\nAula 10 – Iter criminis, tentativa e crime impossível\n\nIter criminis: o caminho do crime\n“Iter criminis” significa o caminho que o crime percorre, da ideia até o fim. Tem quatro\nfases, mais uma depois da consumação:\n\n   1. Cogitação: o agente apenas pensa em cometer o crime. Nunca é punida.\n   2. Atos preparatórios: providências para tornar o crime possível (comprar a arma,\n       estudar o local). Em regra não são punidos, salvo se já forem crime por si só (ex.:\n       possuir petrechos para falsificar moeda, art. 291; associação criminosa).\n   3. Execução: o agente começa a realizar o crime, atacando o bem jurídico. É aqui que a\n       punição começa (tentativa). O critério mais usado (objetivo-formal) é: executar é\n       começar a praticar o verbo do tipo (começar a “matar”, a “subtrair”).\n   4. Consumação (art. 14, I): estão presentes todos os elementos da definição legal do\n       crime.\n   5. Exaurimento: o crime já consumado produz seus efeitos finais, como gastar o dinheiro\n       do resgate. Não muda a consumação, mas pode influenciar a pena.\n\nQuando começa a execução? Três critérios (slides):\n\n       Teoria subjetiva: depende só da intenção do autor. É rejeitada no Brasil, porque viola o\n       princípio da legalidade.\n       Teoria objetivo-formal: execução é começar a realizar o verbo do tipo. É a posição\n       tradicional majoritária.\n       Teoria objetivo-material ou individual: são executórios o verbo do tipo e também os\n       atos imediatamente anteriores (conatus proximus), segundo o plano concreto do\n       autor, quando já geram perigo direto e imediato ao bem jurídico.\n\nO iter criminis só se aplica aos crimes dolosos. A fase interna (cogitação) é impunível\n(cogitationis poenam nemo patitur), e a fase externa começa nos atos preparatórios.\n\n                                                                                             Page 7 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nQuando o crime se consuma? Depende do tipo. Nos crimes materiais, quando ocorre o\nresultado (homicídio: a morte). Nos formais, com a própria conduta, sem precisar do\nresultado (extorsão, Súmula 96 do STJ). Nos de mera conduta, quando a conduta é\npraticada.\n\n\nTentativa (art. 14, II)\nHá tentativa quando o agente inicia a execução, mas o crime não se consuma por\ncircunstâncias alheias à sua vontade. Requisitos:\n\n       dolo de consumar o crime;\n       início da execução (não basta preparar);\n       não consumação;\n       o motivo da não consumação foi alheio à vontade do agente (a vítima foi socorrida, a\n       arma falhou, a polícia chegou).\n\nPena (art. 14, parágrafo único): a do crime consumado, diminuída de 1/3 a 2/3. Quanto mais\no agente avançou no caminho do crime, menor a redução; quanto menos avançou, maior a\nredução.\n\nEspécies de tentativa\n\n       Imperfeita (inacabada): o agente é interrompido antes de usar todos os meios de que\n       dispunha.\n       Perfeita (acabada, ou crime falho): o agente usa todos os meios que tinha, mas o\n       resultado não acontece.\n       Branca: a vítima não é atingida. Cruenta: a vítima é ferida.\n\nNão admitem tentativa: crimes culposos (em regra), preterdolosos, contravenções\npenais (art. 4º da LCP), crimes unissubsistentes (a conduta acontece em um só ato, como\na injúria verbal) e crimes omissivos próprios.\n\n\nDesistência voluntária e arrependimento eficaz (art. 15)\nNesses casos o agente desiste por conta própria e, por isso, responde apenas pelos atos\nque já praticou, não pelo crime que pretendia. A lei exige voluntariedade (ele poderia\ncontinuar), não espontaneidade (a ideia pode ter vindo de outra pessoa).\n\n       Desistência voluntária: o agente para de executar, podendo continuar. Ex.: aponta a\n       arma, poderia atirar e desiste. Fórmula de Frank: “posso, mas não quero”.\n       Arrependimento eficaz: o agente já esgotou os meios, mas age para impedir o\n       resultado e consegue. Ex.: envenena o café, depois dá o antídoto e a vítima se salva.\n\nNa tentativa é o contrário: “quero, mas não posso”. Na prova, repare sempre se a causa de\no crime não ter acontecido foi a vontade do próprio agente ou algo externo.\n\n                                                                                        Page 8 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nOs slides chamam a desistência voluntária e o arrependimento eficaz de “pontes de ouro”\n(expressão de Von Liszt): a lei constrói uma ponte para o agente voltar atrás. A fórmula de\nFrank para o arrependimento eficaz é: “eu fiz tudo o que podia, mas não quero que o\nresultado ocorra”. Quanto à natureza jurídica, o slide da aula trata como atipicidade da\ntentativa (não é extinção da punibilidade do art. 107), embora outro slide use a expressão\n“extinção da punibilidade do crime visado”. Para a prova, o que importa é a consequência:\no agente responde só pelos atos já praticados.\n\n\nArrependimento posterior (art. 16)\nAcontece depois da consumação. Nos crimes sem violência ou grave ameaça, se o\nagente repara o dano ou restitui a coisa voluntariamente, até o recebimento da denúncia\nou da queixa, a pena é reduzida de 1/3 a 2/3.\n\n\n   Instituto                               Quando ocorre                    Efeito\n\n   Tentativa                               Execução interrompida por        Pena do crime consumado\n                                           motivo externo                   reduzida de 1/3 a 2/3\n\n   Desistência                             Agente para sozinho a execução   Responde só pelos atos já\n   voluntária                                                               praticados\n\n   Arrependimento                          Agente esgota os meios, mas      Responde só pelos atos já\n   eficaz                                  evita o resultado                praticados\n\n   Arrependimento                          Depois da consumação, com        Pena reduzida de 1/3 a 2/3\n   posterior                               reparação do dano\n\n\nO arrependimento posterior é a “ponte de prata”. Detalhes dos slides:\n\n       É causa obrigatória de diminuição de pena, aplicada na terceira fase da dosimetria\n       (direito do réu). Não afasta o crime.\n       A fração (1/3 a 2/3) depende da presteza da reparação: quanto mais rápida, maior a\n       redução.\n       A recusa da vítima em aceitar a reparação não impede o benefício: o agente pode\n       depositar em juízo.\n       Há divergência jurisprudencial sobre a extensão do arrependimento posterior aos corréus quando apenas um deles repara o dano. O STJ já reconheceu a comunicabilidade por sua natureza objetiva (REsp 1.187.976/SP, Informativo 531/2013), mas há julgados que exigem reparação voluntária atribuível ao próprio agente. Não trate a extensão como automática: confira o precedente aplicável e as circunstâncias concretas.\n       Não vale para crimes com violência ou grave ameaça, nem com violência imprópria\n       (ex.: dopar a vítima para subtrair bens).\n       Peculato doloso: a reparação até o recebimento da denúncia reduz a pena (art. 16).\n       Peculato culposo: a reparação antes da sentença irrecorrível extingue a punibilidade\n       (art. 312, §3º).\n\n                                                                                                         Page 9 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n       Súmula 554 do STF: o pagamento do cheque sem fundos depois do recebimento da\n       denúncia não impede a ação penal (se for antes, extingue a punibilidade do\n       estelionato).\n\n\nCrime impossível (art. 17)\n“Não se pune a tentativa quando, por ineficácia absoluta do meio ou por absoluta\nimpropriedade do objeto, é impossível consumar-se o crime.” Também chamado de\ntentativa inidônea ou quase-crime.\n\n       Ineficácia absoluta do meio: o meio usado jamais poderia produzir o resultado. Ex.:\n       tentar matar alguém com arma de brinquedo ou com “veneno” que é apenas açúcar.\n       Absoluta impropriedade do objeto: a pessoa ou coisa atacada não pode sofrer o\n       crime. Ex.: atirar em quem já está morto; praticar aborto em mulher que não está\n       grávida.\n\nA palavra-chave é absoluta. Se a ineficácia ou a impropriedade for apenas relativa, existe\ntentativa. Ex.: atirar com uma arma que normalmente funciona, mas falha naquele\nmomento; tentar furtar a bolsa de alguém que, por acaso, estava com ela vazia.\n\nConsequência: o fato é atípico (não há crime). O agente só responde se os atos já\npraticados forem crime por si só.\n\nO CP adota a teoria objetiva temperada: ineficácia ou impropriedade absoluta gera crime\nimpossível (não se pune); relativa gera tentativa (pune-se). O flagrante preparado\n(Súmula 145 do STF) também é chamado de “crime de ensaio” ou delito putativo por obra\nde agente provocador: a polícia anula totalmente a viabilidade do crime.\n\nDuas súmulas importantes:\n\n       Súmula 145 do STF: não há crime quando a preparação do flagrante pela polícia torna\n       impossível a consumação (flagrante preparado: a polícia induz o crime e vigia tudo o\n       tempo todo).\n       Súmula 567 do STJ: sistema de vigilância eletrônica ou segurança dentro da loja, por si só, não torna impossível o furto (a ineficácia é apenas relativa). Isso não define automaticamente se houve tentativa ou consumação: pelo Tema 934/STJ, o furto se consuma com a posse de fato da coisa, ainda que breve e seguida de perseguição; é necessário verificar se houve efetiva inversão da posse. No Informativo 886/2026, o STJ distinguiu a prisão ainda dentro do estabelecimento, antes da inversão efetiva da posse, hipótese em que permanece a tentativa.\n\nNão confunda com crime putativo (imaginário): a pessoa acha que está cometendo um\ncrime, mas o fato é lícito. Ex.: acreditar que adultério ainda é crime e praticá-lo. Também\nnão há crime.\n\n\nAula 11 – Ilicitude (antijuridicidade)\nIlicitude é a contrariedade do fato típico com o ordenamento jurídico como um todo. Regra\nprática: todo fato típico é, em princípio, ilícito. Ele só deixa de ser ilícito se estiver\npresente uma causa de exclusão da ilicitude (também chamadas de excludentes,\n\n                                                                                             Page 10 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\njustificantes ou descriminantes). Se uma delas está presente, não há crime.\n\nEssa ideia vem da teoria da indiciariedade (ratio cognoscendi, de Mayer, 1915): a\ntipicidade é como a fumaça que indica o fogo (a ilicitude). A ilicitude é presumida\n(presunção relativa, juris tantum), até que se prove uma excludente. Pela teoria tripartida,\na ilicitude é o segundo substrato do crime.\n\nO art. 23 lista quatro:\n\n   1. Estado de necessidade (art. 24)\n   2. Legítima defesa (art. 25)\n   3. Estrito cumprimento do dever legal\n   4. Exercício regular de direito\n\nTodas exigem também o elemento subjetivo: o agente precisa saber que está agindo em\ndefesa, em necessidade etc. Quem, por coincidência, mata um inimigo que ia atacá-lo sem\nque ele soubesse, não age em legítima defesa.\n\n\nEstado de necessidade (art. 24)\nAgir em estado de necessidade é sacrificar um bem jurídico para salvar outro, quando há\num perigo atual que o agente não provocou por sua vontade, que não podia evitar de\noutro modo, e o bem salvo é direito próprio ou de terceiro, sendo irrazoável exigir o\nsacrifício do bem que se quer salvar.\n\nExemplo clássico: dois náufragos disputam uma única tábua que só aguenta um. Um deles\nempurra o outro e se salva. Outro exemplo: furtar comida para não morrer de fome,\nquando não havia outro meio.\n\n       O agente não pode alegar estado de necessidade se tinha o dever legal de enfrentar o\n       perigo (art. 24, §1º). Ex.: bombeiro, policial.\n       Se era razoável exigir o sacrifício do bem, o agente ainda responde, mas com pena\n       reduzida de 1/3 a 2/3 (art. 24, §2º).\n       O CP adotou a teoria unitária: o estado de necessidade exclui a ilicitude quando o\n       bem salvo vale igual ou mais que o sacrificado. (O Código Penal Militar adota a\n       diferenciadora.)\n\nDetalhes dos slides sobre os requisitos do estado de necessidade:\n\n       Perigo atual ou iminente: a doutrina e a jurisprudência majoritárias aceitam também o\n       perigo iminente (interpretação favorável ao réu do art. 24). O perigo é presente, real e\n       sem destinatário certo (desastre natural, ataque espontâneo de animal).\n       Não provocação voluntária: quem se coloca dolosamente em risco não pode alegar a\n       excludente. Se a provocação foi culposa, a doutrina se divide.\n\n                                                                                         Page 11 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n       Inevitabilidade: o sacrifício do bem alheio deve ser a única saída. Se era possível fugir\n       (commodus discessus), a fuga é exigida e vem primeiro.\n       Proporcionalidade: o bem salvo deve valer igual ou mais que o sacrificado. Se o bem\n       sacrificado valia mais, o fato continua ilícito, mas a pena é reduzida de 1/3 a 2/3 (art. 24,\n       §2º).\n       Dever legal: bombeiro, policial e salva-vidas não podem alegar estado de necessidade,\n       salvo na impossibilidade absoluta de salvamento.\n\n\nLegítima defesa (art. 25)\nEstá em legítima defesa quem, usando moderadamente os meios necessários, repele\ninjusta agressão, atual ou iminente, a direito seu ou de outra pessoa.\n\nRequisitos, que precisam estar todos presentes:\n\n       Agressão injusta: contrária ao direito (não precisa ser crime). Contra agressão justa,\n       como a de um policial prendendo alguém em flagrante, não há legítima defesa.\n       Atual ou iminente: está acontecendo ou prestes a acontecer. Agressão passada vira\n       vingança; agressão futura e incerta não autoriza reação.\n       Direito próprio ou de terceiro: vida, integridade, patrimônio, honra etc.\n       Meios necessários: os meios disponíveis e suficientes, nas circunstâncias concretas, para repelir a agressão; necessidade e moderação são avaliadas no caso, sem fórmula abstrata de que sempre se deve escolher o meio menos lesivo.\n       Uso moderado: parar quando a agressão cessa. Continuar depois é excesso.\n       Conhecimento da situação (elemento subjetivo).\n\nO parágrafo único do art. 25 (incluído pela Lei 13.964/2019, o “pacote anticrime”) diz que\ntambém age em legítima defesa o agente de segurança pública que repele agressão ou\nrisco de agressão a vítima mantida refém durante a prática de crimes.\n\nO STF decidiu (ADPF 779) que a chamada “legítima defesa da honra” é inconstitucional:\nnão pode ser usada como tese de defesa, por exemplo, em casos de feminicídio.\n\nMais detalhes dos slides sobre a legítima defesa:\n\n       A agressão deve ser humana. O ataque de animal só autoriza legítima defesa se o\n       animal foi usado como instrumento (arma) por uma pessoa.\n       A legítima defesa real é justificante: exclui a ilicitude. Impõe absolvição sumária (art.\n       397, I, do CPP) ou absolvição na sentença (art. 386, VI, do CPP).\n       Não existe legítima defesa recíproca (legítima defesa de legítima defesa), porque a\n       reação de quem se defende não é injusta. É possível, porém, legítima defesa contra o\n       excesso (quando a reação passa da moderação e vira agressão).\n       Legítima defesa putativa (art. 20, §1º): o agente reage a uma agressão que só existe\n       na sua cabeça. É um erro de tipo permissivo (exclui o dolo, e pune-se por culpa se o\n       erro era evitável).\n\n                                                                                            Page 12 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n       O parágrafo único do art. 25 (agente de segurança e refém) é visto por parte da\n       doutrina como “pleonasmo legislativo”, porque a legítima defesa de terceiro já estava\n       no caput.\n       Efeitos civis: quem age em legítima defesa não comete ato ilícito civil (art. 188, I, do\n       Código Civil) e, em regra, não indeniza o agressor. Se atingir um inocente por erro na\n       execução, deve indenizar esse terceiro, com direito de regresso contra o agressor\n       (art. 930, parágrafo único, do CC).\n\nDiferença entre legítima defesa e estado de necessidade\n\n\n                                      Legítima defesa                 Estado de necessidade\n\n   O que existe                       Agressão injusta (de uma        Perigo (de qualquer origem: natureza,\n                                      pessoa)                         animal, pessoa)\n\n   Contra quem se                     Contra o próprio agressor       Normalmente contra um terceiro\n   age                                                                inocente\n\n   Conflito                           Interesse ilícito x interesse   Dois bens lícitos em conflito\n                                      lícito\n\n\nOutras diferenças que os slides destacam: na legítima defesa, a fuga não é exigida\n(ninguém precisa se acovardar diante de agressão injusta); no estado de necessidade, a\nfuga ou o desvio é prioritário e o sacrifício do bem de terceiro deve ser a última saída.\nQuanto aos animais: ataque espontâneo ou irrefletido é estado de necessidade; animal\nusado como arma por uma pessoa é legítima defesa.\n\n\nEstrito cumprimento do dever legal e exercício regular de direito\n       Estrito cumprimento do dever legal: o agente, normalmente agente público, pratica o\n       fato porque a lei manda. Ex.: policial que algema e prende em flagrante, usando a força\n       necessária; oficial de justiça que arromba a porta para cumprir ordem judicial quando\n       autorizado.\n       Exercício regular de direito: o agente faz algo permitido pelo ordenamento. Ex.:\n       lesões causadas em lutas esportivas regulamentadas; intervenção cirúrgica feita com\n       consentimento; particular que prende alguém em flagrante (o CPP permite). Também\n       as defesas preparadas (“ofendículos”), como cerca elétrica ou cacos de vidro no muro,\n       desde que proporcionais.\n\nRegras dos slides:\n\n       Estrito cumprimento do dever legal: o dever deve vir da lei (em sentido amplo, como\n       leis e regulamentos), não de contrato ou obrigação privada. O agente deve agir\n       estritamente nos limites legais, sob pena de excesso. Aplica-se sobretudo a agentes\n\n                                                                                                         Page 13 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n       públicos (policiais, oficiais de justiça), mas também a particulares em serviço público\n       obrigatório (jurados, mesários). Exemplo: o crime de cárcere privado (art. 148) não\n       existe para o policial que prende em flagrante, porque o art. 292 do CPP impõe esse\n       dever.\n       Exercício regular de direito é uma faculdade do cidadão, e não uma obrigação\n       imposta pelo Estado. Vale o princípio da unidade do ordenamento: o que outro ramo\n       do direito permite ou incentiva não pode ser ilícito penal. Exemplos: lesões de esporte\n       dentro das regras, cirurgia com consentimento.\n       Ofendículos (cacos de vidro, cercas elétricas, concertinas) são exercício regular de\n       direito enquanto instalados e inertes, e viram legítima defesa preordenada quando\n       atingem um invasor. Devem ser visíveis, moderados e previsíveis. Armadilha letal ou\n       escondida não tem amparo e gera excesso doloso.\n\nAmbas só valem dentro do limite legal. Se o agente se excede, responde pelo excesso.\n\n\nExcesso (art. 23, parágrafo único)\nQuem ultrapassa os limites de uma excludente responde pelo excesso:\n\n       Excesso doloso: o agente sabe que a agressão cessou ou que já podia se defender\n       com menos violência, mas continua. Responde por crime doloso.\n       Excesso culposo: o agente erra por falta de cuidado ao avaliar o que era necessário.\n       Responde por crime culposo, se existir essa forma.\n\nO excesso se divide em extensivo (o agente continua a agir depois que a agressão ou o\nperigo acabou) e intensivo (usa meios desproporcionais desde o início). Em qualquer\ndeles, pode ser:\n\n       Doloso: o agente sabe que passou do limite. Responde pelo crime doloso.\n       Culposo: avalia mal a situação por imprudência, negligência ou imperícia. Responde\n       por crime culposo, se ele existir (ex.: homicídio culposo).\n       Exculpante: o excesso vem de pânico, medo insuperável, perturbação ou choque\n       emocional violento causado pela agressão. A conduta é inexigível e o agente fica\n       isento de pena (excludente de culpabilidade).\n\nO excesso punível vale para todas as justificantes, não só a legítima defesa.\n\n\nConsentimento do ofendido\nNão está listado no art. 23, mas a doutrina aceita como causa supralegal de exclusão da\nilicitude quando o bem é disponível (como o patrimônio), o ofendido é capaz e o\nconsentimento é anterior ou simultâneo ao fato. Não vale para a vida, por exemplo.\n\n                                                                                        Page 14 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nAtenção com a fronteira da tipicidade: se a falta de consentimento (o dissenso) já é\nelemento do próprio tipo (violação de domicílio, art. 150; cárcere privado, art. 148; estupro,\nart. 213), o consentimento da vítima exclui a tipicidade, e não a ilicitude.\n\nRoteiro de diagnóstico das excludentes (fluxograma dos slides)\n\n   1. Houve agressão humana injusta, atual ou iminente? Sim: legítima defesa.\n   2. Havia perigo atual ou iminente a bens em conflito? Sim: estado de necessidade.\n   3. A lei obrigava a ação? Sim: estrito cumprimento do dever legal.\n   4. A lei permitia ou incentivava a ação? Sim: exercício regular de direito.\n   5. Houve consentimento válido para bem disponível? Sim: consentimento do ofendido\n       (causa supralegal).\n   6. Se nenhuma se aplica, o fato é ilícito e se passa à análise da culpabilidade.\n\nSe alguma se aplica, a absolvição é pelo art. 386, VI, do CPP (para quem adota a tipicidade\nconglobante, no estrito cumprimento, a absolvição é pelo art. 386, III).\n\n\nAula 12 – Culpabilidade\nCulpabilidade é o juízo de reprovação, ou seja, de censura, sobre quem praticou um fato\ntípico e ilícito. Responde à pergunta: “esta pessoa merece ser punida por isso?”. É o último\npasso da análise do crime.\n\nPela teoria normativa pura, adotada pelo finalismo e pelo CP, os elementos da\nculpabilidade são três:\n\n   1. Imputabilidade\n   2. Potencial consciência da ilicitude\n   3. Exigibilidade de conduta diversa\n\nSe falta qualquer um, o agente é isento de pena (o crime existe, mas ele não é punido). O\ndolo e a culpa não estão aqui: já foram analisados na tipicidade.\n\n\nComo a teoria da culpabilidade evoluiu (slides da aula 12)\n\n   Teoria                                  Ideia central                   Onde ficam dolo e culpa\n\n   Psicológica (sistema                    Culpabilidade é o vínculo       Dentro da culpabilidade\n   clássico)                               psicológico entre o autor e o\n                                           fato\n\n                                                                                               Page 15 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n   Teoria                                  Ideia central                    Onde ficam dolo e culpa\n\n   Psicológico-normativa                   Culpabilidade é juízo de         Dentro da culpabilidade\n   (neoclássica, de Frank)                 reprovabilidade:\n                                           imputabilidade + dolo ou culpa\n                                           + exigibilidade de conduta\n                                           diversa\n\n   Normativa pura (finalista)              Juízo de valor puro:             Saem da culpabilidade e\n                                           imputabilidade + potencial       vão para o fato típico\n                                           consciência da ilicitude +\n                                           exigibilidade de conduta\n                                           diversa\n\n\nA teoria adotada é a normativa pura, e é por isso que a culpabilidade só tem os três\nelementos abaixo.\n\n\n1. Imputabilidade\nÉ a capacidade de entender o caráter ilícito do fato e de se determinar de acordo com\nesse entendimento. Presume-se que todo adulto é imputável. As causas que excluem a\nimputabilidade são:\n\nDoença mental ou desenvolvimento mental incompleto ou retardado (art. 26)\n\n       Se, ao tempo do fato, o agente era inteiramente incapaz de entender o caráter ilícito\n       ou de se determinar, ele é inimputável: isento de pena. O juiz o absolve (“absolvição\n       imprópria”) e aplica medida de segurança.\n       Se a capacidade estava apenas reduzida (art. 26, parágrafo único), ele é semi-\n       imputável: continua condenado, com pena reduzida de 1/3 a 2/3, ou o juiz pode\n       substituir a pena por medida de segurança.\n       Adota-se o critério biopsicológico: não basta ter a doença; é preciso que ela tenha\n       retirado a capacidade no momento do fato.\n\nTempo da medida de segurança. A Súmula 527 do STJ estabelece que a duração não deve ultrapassar a pena máxima abstratamente cominada ao delito. O limite de 40 anos do art. 75 do CP é aplicado como teto adicional por analogia, observando-se o limite mais favorável no caso concreto; não significa que toda medida possa durar 40 anos. A política antimanicomial (Resolução 487/2023 do CNJ e Lei 10.216/2001) prioriza o cuidado em liberdade e o tratamento na rede de atenção psicossocial, com internação apenas quando indicada e nos termos legais.\n\nMenoridade (art. 27)\n\nMenores de 18 anos são inimputáveis (critério biológico, só a idade importa). Respondem\npelo Estatuto da Criança e do Adolescente (ECA), com medidas socioeducativas, não com\npena.\n\n                                                                                                Page 16 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nEmbriaguez (art. 28)\n\n       Emoção e paixão não excluem a imputabilidade.\n       Embriaguez voluntária ou culposa (a pessoa bebeu por vontade ou sem cuidado) não\n       exclui a culpabilidade, mesmo que completa. Isso se explica pela teoria da actio libera\n       in causa (ação livre na causa): a pessoa era livre quando decidiu se embriagar, então\n       responde pelo que fizer depois.\n       Embriaguez completa por caso fortuito ou força maior (art. 28, §1º), como ser\n       forçada a beber ou beber sem saber o que continha a bebida: o agente fica isento de\n       pena.\n       Se a embriaguez fortuita é apenas parcial, a pena é reduzida de 1/3 a 2/3 (art. 28, §2º).\n\nDetalhes que a professora destaca nos slides:\n\n       Embriaguez patológica (alcoolismo crônico) é tratada como doença mental (art. 26).\n       Embriaguez preordenada (beber para ganhar coragem e cometer o crime) é\n       agravante (art. 61, II, l).\n       A actio libera in causa tem dois tempos. No tempo 1, o agente é livre e consciente ao\n       decidir beber. No tempo 2, pratica o crime já inimputável. A imputabilidade “retroage”\n       ao tempo 1, e por isso ele responde pelo crime. Há crítica a essa teoria quando a\n       embriaguez é apenas voluntária ou culposa (sem intenção de cometer crime): ela\n       pode virar uma responsabilidade penal objetiva disfarçada.\n\n\n2. Potencial consciência da ilicitude\nPara ser punido, o agente deve saber, ou ao menos poder saber, que o que faz é proibido.\nNão precisa conhecer o artigo de lei; basta ter a noção de que é errado (o que a doutrina\nchama de “valoração paralela na esfera do profano”). Se não tinha essa possibilidade,\nocorre erro de proibição inevitável, estudado na aula 13.\n\n\n3. Exigibilidade de conduta diversa\nPara punir alguém, é preciso que dele se pudesse esperar um comportamento diferente.\nQuando as circunstâncias eram tão anormais que ninguém conseguiria agir de outro\nmodo, a conduta é inexigível. O art. 22 prevê dois casos (só punido o autor da coação ou\nda ordem):\n\n       Coação moral irresistível: o agente é ameaçado de um mal grave e faz o que o coator\n       manda. Ex.: obrigar o caixa, sob a ameaça de matar sua família, a abrir o cofre. Só\n       responde o coator.\n       Obediência hierárquica: o subordinado cumpre ordem não manifestamente ilegal de\n       superior hierárquico, no serviço público. Só responde quem deu a ordem. Se a ordem\n       era claramente ilegal, o subordinado também responde.\n\n                                                                                         Page 17 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nAtenção para não confundir: a coação física irresistível (o agente é empurrado ou\nimobilizado e usado como instrumento) exclui a própria conduta (não há ação voluntária),\nportanto o fato nem chega a ser típico. A coação moral exclui a culpabilidade.\n\nCoação moral resistível. Se o coagido poderia resistir, a culpabilidade não é excluída: ele\nresponde pelo crime, com pena atenuada (art. 65, III, c). O coator também responde, com\nagravante (art. 62, II).\n\nRequisitos da obediência hierárquica (todos devem estar presentes):\n\n   1. Relação de direito público: subordinação administrativa oficial (não vale para chefe de\n       empresa privada).\n   2. Ordem não manifestamente ilegal: ela tem aparência de legalidade.\n   3. Estrita obediência: o subordinado faz só o que foi ordenado, sem excessos.\n\nSe a ordem for manifestamente ilegal (ex.: matar alguém), o superior e o subordinado\nrespondem pelo crime, com atenuante para o subordinado (art. 65, III, c).\n\nCausas supralegais. Doutrina e jurisprudência aceitam outras situações de inexigibilidade\nde conduta diversa que não estão escritas na lei. Exemplo citado nos slides: dificuldades\nfinanceiras extremas da empresa, com risco de falência e desemprego coletivo, em crimes\nde omissão tributária.\n\nComo o juiz absolve. Excluída a culpabilidade, a absolvição é com base no art. 386, VI, do\nCPP. Se o caso é de doença mental, a absolvição é imprópria: o réu é absolvido, mas\nrecebe medida de segurança (art. 26).\n\n\n   Elemento                                Se faltar                   Exemplos\n\n   Imputabilidade                          Isenção de pena (art. 26,   Doença mental, menoridade,\n                                           27 e 28, §1º)               embriaguez fortuita completa\n\n   Potencial consciência da                Erro de proibição           Agente que não tinha como saber\n   ilicitude                               inevitável (art. 21)        que era proibido\n\n   Exigibilidade de conduta                Isenção de pena (art. 22)   Coação moral irresistível,\n   diversa                                                             obediência hierárquica\n\nAula 13 – Teoria do erro\nErro é a falsa percepção da realidade: a pessoa acha que algo é de um jeito, mas é de\noutro. O Direito Penal separa dois grandes tipos, e a diferença entre eles é pergunta\nfrequente de prova.\n\n                                                                                                    Page 18 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nErro de tipo (art. 20)\nÉ o erro sobre um elemento do tipo penal: o agente não sabe que está praticando o fato\ndescrito na lei. Como o dolo é saber e querer, quem não sabe não tem dolo. Por isso o erro\nde tipo sempre exclui o dolo.\n\nExemplo: no ponto de ônibus, uma pessoa pega uma mochila igual à sua, achando que é\ndela. Não tem dolo de “subtrair coisa alheia”, porque acreditava ser sua. Não há furto.\n\nO erro de tipo essencial pode ser:\n\n       Inevitável (escusável): qualquer pessoa cuidadosa teria errado. Exclui o dolo e a\n       culpa. O fato é atípico.\n       Evitável (inescusável): com mais cuidado, o erro seria evitado. Exclui o dolo, mas o\n       agente responde por culpa, se o crime existir na forma culposa.\n\nComo separar erro essencial de acidental (teste dos slides): se o agente fosse avisado\ndo erro, o que ele faria? No erro essencial, ele para (percebe que a bolsa é de outra\npessoa e devolve). No erro acidental, ele continua e só corrige a rota (percebe que o\nrelógio não é de ouro, mas furta mesmo assim).\n\nFiltro da evitabilidade: pergunte se uma pessoa comum (“homem médio”), nas mesmas\ncircunstâncias, teria evitado o erro. Se teria, o erro é evitável; se não, é inevitável.\n\nErro de tipo acidental (não exclui o dolo, o agente continua respondendo pelo crime)\n\n       Erro sobre a pessoa (art. 20, §3º): o agente atinge uma pessoa pensando que era\n       outra. Responde como se tivesse atingido a pessoa que queria atingir (levam-se em\n       conta as qualidades da vítima pretendida). Ex.: quer matar A, confunde B com A e\n       mata B: responde como se tivesse matado A.\n       Erro na execução (aberratio ictus, art. 73): por acidente ou erro no uso dos meios, o\n       agente atinge pessoa diferente da que queria. Responde como se tivesse atingido a\n       pretendida. Se atingir as duas pessoas, há concurso formal (art. 70). Ex.: atira em A,\n       erra e acerta B.\n       Resultado diverso do pretendido (aberratio criminis, art. 74): o agente quer produzir\n       um resultado e provoca outro, de outro crime. Ex.: joga uma pedra para quebrar a\n       vidraça (dano) e acerta uma pessoa. Responde por culpa do resultado produzido, se\n       existir essa forma. Se produz também o resultado pretendido, há concurso formal.\n       Dolo geral (erro sucessivo): o agente acha que já consumou o crime e, ao tentar\n       esconder o fato, é essa segunda conduta que causa o resultado. Ex.: atira e, pensando\n       que a vítima morreu, joga o corpo no rio; ela morre afogada. Para a doutrina majoritária,\n       responde por homicídio doloso consumado.\n\nSe o erro foi provocado por terceiro (art. 20, §2º), responde o terceiro que provocou o\nerro.\n\n                                                                                           Page 19 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nDescriminantes putativas (art. 20, §1º)\nÉ o erro sobre uma situação de fato que, se fosse real, tornaria a ação legítima. Ex.: o\nagente vê um amigo se aproximando de madrugada, acha que é um assaltante e atira em\n“legítima defesa”. Se o erro era plenamente justificado pelas circunstâncias, ele é isento\nde pena. Se era evitável, responde por culpa (se o crime existir na forma culposa).\n\nAs descriminantes putativas se chamam assim porque o agente imagina que estava em\nlegítima defesa, estado de necessidade etc., mas na verdade não estava.\n\nO CP segue a teoria limitada da culpabilidade. Por ela, o erro sobre a situação de fato\n(achou que era uma arma, mas era um celular) é erro de tipo permissivo: se inevitável,\nisenta de pena; se evitável, o agente responde por crime culposo, o que se chama de\nculpa imprópria (ele quis o resultado, mas a lei o pune como se fosse culposo, por política\ncriminal). Já o erro sobre a existência ou os limites da excludente (achar que a lei permite\nmatar por ofensa verbal) é erro de proibição indireto: se inevitável, isenta; se evitável,\nreduz a pena de 1/6 a 1/3, e o crime continua doloso.\n\nPor isso a culpa própria (a comum, por imprudência, negligência ou imperícia) é diferente\nda culpa imprópria (a que vem de uma descriminante putativa evitável).\n\n\nErro de proibição (art. 21)\nO agente sabe exatamente o que está fazendo, mas acredita que sua conduta é\npermitida. Ele erra sobre a ilicitude do fato, e não sobre a realidade. Atinge o elemento\n“potencial consciência da ilicitude” da culpabilidade.\n\n       Inevitável: o agente não tinha como saber que era proibido. É isento de pena.\n       Evitável: com algum esforço, poderia saber. A pena pode ser reduzida de 1/6 a 1/3. O\n       crime existe, e o dolo também.\n\nCuidado: “o desconhecimento da lei é inescusável” (art. 21, caput). Não saber que existe\numa lei não livra ninguém; apenas o erro sobre a ilicitude do fato é relevante, e só se for\ninevitável isenta de pena (ou reduz, se evitável). Ex.: o estrangeiro que, no país dele,\npraticava um ato permitido e vem para o Brasil, onde é crime, sem poder saber disso.\n\nHá também o erro de proibição indireto: o agente conhece os fatos, mas erra sobre a\nexistência ou os limites de uma excludente de ilicitude. Ex.: acha que a lei autoriza matar\nquem invade sua propriedade.\n\nOs slides separam o erro de proibição em três espécies:\n\n       Direto: o erro recai sobre a própria norma proibitiva (o agente desconhece que aquilo\n       é proibido). Ex.: turista que traz uma semente permitida no país dele.\n\n                                                                                       Page 20 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n       Indireto (erro de permissão): o agente sabe que a conduta é proibida em regra, mas\n       acha que existe uma causa que a permite, ou erra sobre seus limites. Ex.: o credor que\n       pega o relógio do devedor para cobrar a dívida (art. 345, exercício arbitrário das\n       próprias razões).\n       De mandamento: nos crimes omissivos, o agente erra sobre o dever de agir. Ex.: o\n       salva-vidas que acredita não ter o dever de resgatar alguém fora do horário do posto.\n\nNo erro de proibição, o critério não é o “homem médio”, e sim o perfil sociocultural do\nagente (instrução, cultura, meio social e condições pessoais). A pergunta é: com essa\nvivência, era possível a ele compreender que o fato era proibido?\n\nAtenção com a jurisprudência do STJ, que os slides citam para ribeirinhos e moradores\nrurais (crimes ambientais, armas sem registro): o mero desconhecimento formal da lei não\nbasta. O STJ exige prova de que era concretamente impossível para aquela pessoa\nperceber que o ato era proibido. Por isso, no caso do pescador João (veja a seção de\nquestões no fim), a isenção só aparece porque o enunciado diz que isso ficou “fartamente\ndemonstrado”.\n\n\n                             Erro de tipo                              Erro de proibição\n\n   Sobre o                   Um elemento do tipo (a                    A ilicitude do fato (se é permitido ou\n   quê                       realidade)                                proibido)\n\n   Atinge                    O dolo (fato típico)                      A culpabilidade\n\n   Se                        Exclui dolo e culpa (fato atípico)        Isenta de pena\n   inevitável\n\n   Se evitável               Responde por culpa (se prevista)          Pena reduzida de 1/6 a 1/3\n\n   Exemplo                   Pega a mochila alheia achando             Sabe que está pegando algo, mas acha\n                             que é a sua                               que a lei permite\n\n\nErro de tipo x delito putativo (crime imaginário)\n\n\n                                      Erro de tipo                           Delito putativo\n\n   O que o agente                     Que o fato é lícito ou indiferente     Que o fato é crime\n   pensa\n\n   O que                              Crime (falta ao agente o               Fato lícito ou atípico\n   realmente é                        conhecimento de um elemento do\n                                      tipo)\n\n                                                                                                           Page 21 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n                                      Erro de tipo                        Delito putativo\n\n   Exemplo dos                        Atira em uma pessoa viva achando    Atira em uma estátua de cera\n   slides                             que é um boneco de cera             achando que é uma pessoa viva\n                                                                          (crime impossível por absoluta\n                                                                          impropriedade do objeto, art. 17)\n\n\nResumo do caminho de raciocínio (fluxograma dos slides)\n\n   1. O agente teve falsa percepção da realidade dos fatos? Se sim, é erro de tipo. Uma\n       pessoa comum teria evitado o erro? Se sim, pune-se por culpa (se existir a forma\n       culposa). Se não, o fato é atípico (absolvição pelo art. 386, III, do CPP).\n   2. Se ele sabia o que fazia, mas ignorava que era proibido, é erro de proibição. Com o\n       perfil sociocultural dele, era possível entender a ilicitude? Se sim, crime doloso com\n       pena reduzida de 1/6 a 1/3. Se não, isento de pena (absolvição pelo art. 386, VI, do\n       CPP).\n\n\nAula 14 – Concurso de pessoas\nConcurso de pessoas é quando duas ou mais pessoas colaboram para o mesmo crime. O\nart. 29 resume a regra: quem, de qualquer modo, concorre para o crime responde pelas\npenas a ele cominadas, na medida de sua culpabilidade.\n\n\nTeoria adotada: monista (unitária)\nTodos os que contribuem para o crime respondem pelo mesmo crime, cada um com a\npena adequada à sua culpa. O CP faz algumas exceções (teoria pluralista), quando o\nmesmo fato aparece em tipos diferentes para cada pessoa. Exemplos: corrupção ativa\n(art. 333) e passiva (art. 317); aborto provocado pela gestante (art. 124) e aborto feito por\nterceiro com consentimento (art. 126).\n\n\n   Teoria                         Ideia                                  No Código Penal\n\n   Monista                        Crime único para todos os              Adotada, na forma temperada\n   (unitária)                     envolvidos                             (mitigada): as penas são\n                                                                         individualizadas conforme a\n                                                                         culpabilidade de cada um (art. 29)\n\n   Dualista                       Um crime para os autores e outro       Não adotada\n                                  para os partícipes\n\n   Pluralista                     Cada participante responde por         Só nas exceções legais (aborto, arts.\n                                  um crime próprio                       124 e 126; corrupção, arts. 317 e 333)\n\n                                                                                                         Page 22 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nRequisitos\n   1. Pluralidade de agentes e de condutas\n   2. Relevância causal de cada conduta: a contribuição precisa ter influído de algum modo\n       no crime\n   3. Vínculo subjetivo (liame psicológico): cada um sabe que está colaborando com a\n      conduta do outro. Não precisa de combinação prévia; basta a adesão consciente\n   4. Unidade de infração para todos (mesmo crime)\n\n\nAutor, coautor e partícipe\n       Autor: quem realiza a conduta descrita no tipo ou tem o domínio do fato, isto é,\n       controla se o crime ocorre, como e quando (teoria do domínio do fato, majoritária na\n       doutrina atual).\n       Coautor: quem divide com outro a execução do crime, mesmo que cada um faça uma\n       parte diferente (divisão de tarefas). Ex.: em um roubo, um segura a vítima e outro pega\n       a carteira.\n       Partícipe: quem não executa o núcleo do tipo, mas contribui para o crime de forma\n       secundária. A participação pode ser:\n               moral: induzir (criar a ideia criminosa na cabeça de quem ainda não pensava nisso)\n               ou instigar (reforçar uma ideia que já existia);\n               material (cumplicidade ou auxílio): ajudar de forma concreta. Ex.: emprestar a\n               arma ou o carro.\n       Autoria mediata: o autor usa outra pessoa como instrumento, que age sem dolo ou\n       sem culpabilidade (inimputável, pessoa em erro ou sob coação). Ex.: convencer um\n       menor de idade a cometer o crime. Quem usa o instrumento é o autor; o instrumento é\n       só “o meio”.\n       Autor intelectual: quem planeja e comanda o crime (mandante), mas não o executa.\n\nComo separar autor de partícipe. Pela regra legal (teoria objetivo-formal), autor é quem\nrealiza o verbo do tipo. Na doutrina e nos tribunais, usa-se a teoria do domínio do fato\n(Welzel e Roxin): autor é quem tem o controle final do crime ou exerce papel essencial no\nplano global.\n\nAtenção com o motorista da fuga e o “olheiro”. O STJ já reconheceu coautoria funcional quando há ajuste prévio e a função de vigilância, apoio ou fuga integra de modo relevante a execução do plano (por exemplo, HC 20.819/MS). Isso não é automático: a classificação depende do vínculo subjetivo, da relevância causal e do papel efetivamente desempenhado. Quem apenas empresta um bem antes, sem integrar a execução, pode responder como partícipe por auxílio material.\n\nParticipação moral, em uma imagem dos slides: induzir é “plantar a semente” da ideia\ncriminosa; instigar é “regar a semente” de uma ideia que já existia.\n\n                                                                                          Page 23 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nAutoria mediata e aparatos organizados de poder. Além do autor que usa um inocente\ncomo instrumento (por exemplo, entregar veneno a uma enfermeira dizendo que é\nremédio), existe a teoria do domínio da organização (Roxin): o chefe de uma estrutura\nhierárquica em que os executores são substituíveis é autor mediato dos crimes dos\nsubordinados, mesmo que estes também respondam. O STF aplicou essa tese no\nMensalão (Ação Penal 470), e ela é usada contra líderes de facções que ordenam crimes\nde dentro de presídios.\n\nA participação é acessória: o partícipe só responde se o autor praticar pelo menos um\nfato típico e ilícito (acessoriedade limitada). E, segundo o art. 31, o ajuste, a determinação,\na instigação e o auxílio não são puníveis se o crime não chega nem a ser tentado.\n\n\nParticipação de menor importância (art. 29, §1º)\nSe a contribuição foi de menor importância, a pena é reduzida de 1/6 a 1/3. Ex.: quem\napenas empresta um objeto sem grande relevância para o plano.\n\nA posição predominante reserva a causa de diminuição do art. 29, §1º, ao partícipe, e não ao coautor que exerce domínio funcional relevante. O STJ afasta a minorante quando a atuação do agente — como motorista ou vigilante previamente ajustado — é essencial ao plano, mas a conclusão depende das provas do caso. Não confunda participação inócua, sem contribuição causal relevante, com participação de menor importância, que é punível com redução de pena.\n\n\nCooperação dolosamente distinta (art. 29, §2º)\nSe um dos concorrentes quis participar de crime menos grave, responde por ele. A pena\né aumentada até a metade se o resultado mais grave era previsível. Ex.: A e B combinam um furto; B, sem avisar, mata o morador. A responde pelo crime menos grave que quis, com possível aumento de até metade se o resultado mais grave era previsível (art. 29, §2º). B responde pelo crime correspondente à sua própria conduta; latrocínio exige subtração mediante violência ou grave ameaça, e não decorre automaticamente de qualquer homicídio praticado durante um furto.\n\nNo roubo, a morte pode caracterizar latrocínio e a Súmula 610 do STF estabelece que o delito se consuma com a morte, ainda que a subtração não se efetive. A responsabilidade de cada concorrente, porém, exige análise individual do vínculo subjetivo, da contribuição e da previsibilidade do resultado; não se presume apenas pela presença no grupo ou pelo emprego de arma.\n\n\nComunicabilidade das circunstâncias (art. 30)\n“Não se comunicam as circunstâncias e as condições de caráter pessoal, salvo quando\nelementares do crime.”\n\n       Elementar é um dado que faz parte da definição do crime. Se o crime não existe sem\n       ela, a elementar se comunica ao coautor ou partícipe, desde que ele saiba da\n       condição. Ex.: no peculato, ser funcionário público é elementar; o particular que ajuda\n\n                                                                                        Page 24 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n       o funcionário também responde por peculato. No infanticídio, o estado puerperal é\n       elementar; quem ajuda a mãe responde por infanticídio, segundo a corrente\n       majoritária.\n       Circunstância é um dado que só agrava ou atenua a pena. As de caráter pessoal\n       (reincidência, motivo pessoal do agente) não se comunicam; as objetivas, sim, desde\n       que o outro saiba.\n\nTeste de comunicabilidade em três perguntas (slides):\n\n   1. É condição ou circunstância pessoal? Não se comunica (ex.: reincidência).\n   2. É circunstância objetiva, ligada ao fato? Comunica-se, desde que conhecida dos\n       comparsas.\n   3. É elementar do crime? Comunica-se, seja pessoal ou objetiva, desde que tenha\n       entrado no dolo dos comparsas (ex.: ser funcionário público no peculato).\n\n\nOutras situações\n       Autoria colateral: duas pessoas agem para o mesmo resultado sem saber uma da\n       outra (sem vínculo subjetivo). Não há concurso: cada uma responde pelo que fez.\n       Autoria incerta: na autoria colateral, não se sabe qual dos dois causou o resultado. Na\n       dúvida, ambos respondem por tentativa (princípio do in dubio pro reo).\n       Crimes multitudinários: praticados sob a influência de multidão em tumulto. Quem\n       não provocou o tumulto tem a pena atenuada (art. 65, III, e).\n       Crimes de concurso necessário (plurissubjetivos): só existem com pluralidade de\n       pessoas, como associação criminosa e rixa. Já os de concurso eventual podem ser\n       praticados por uma pessoa só ou em grupo, como o roubo.\n\nNos slides aparece também que o concurso é possível em crime culposo na forma de\ncoautoria (dois motoristas imprudentes que causam o acidente juntos, por exemplo). Para\na participação em crime culposo, a posição mais aceita é que ela não existe.\n\n\nRevisão rápida: os pontos que mais caem\n       Dolo eventual x culpa consciente: nos dois há previsão; no dolo, o agente aceita o\n       risco; na culpa, acha que não vai acontecer.\n       Crime impossível: só é impossível se a ineficácia do meio ou a impropriedade do\n       objeto for absoluta. Se for relativa, é tentativa.\n       Desistência voluntária: “posso, mas não quero”. Tentativa: “quero, mas não posso”.\n       Arrependimento eficaz acontece antes da consumação; arrependimento posterior\n       acontece depois, com reparação do dano, em crime sem violência ou grave ameaça,\n       até o recebimento da denúncia.\n\n                                                                                       Page 25 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n        Legítima defesa: agressão injusta, atual ou iminente, meios necessários e uso\n        moderado.\n        Estado de necessidade: perigo atual, não provocado pelo agente, inevitável de outro\n        modo. Não vale para quem tem o dever legal de enfrentar o perigo.\n        Inimputável (art. 26): isento de pena, medida de segurança. Semi-imputável: pena\n        reduzida de 1/3 a 2/3.\n        Embriaguez voluntária ou culposa não exclui a culpabilidade. Só a fortuita e completa\n        isenta.\n        Erro de tipo exclui o dolo; erro de proibição exclui (ou reduz) a culpabilidade.\n        Concurso de pessoas: teoria monista. O que não se comunica são as circunstâncias\n        pessoais; as elementares se comunicam.\n\n\nQuestões dos slides (aulas 9 a 14), com a resolução\nOs slides trazem casos práticos de “Direito Penal Aplicado”, com alternativas. É o tipo de\npergunta que costuma ir para a prova. Aqui está cada caso, a resposta dos slides e o\nraciocínio:\n\n\n   Aula         Caso                         Resposta               Raciocínio\n\n   12           Mário bebeu e, sem           B: isento de pena      Embriaguez completa por\n                saber, tomou um                                     caso fortuito ou força maior\n                coquetel misturado por                              exclui a imputabilidade (art.\n                um terceiro; ficou                                  28, §1º)\n                inconsciente e feriu um\n                colega\n\n   12           Carlos sabia que fica        A: tese da defesa      A embriaguez voluntária\n                agressivo quando bebe,       rejeitada              não exclui a imputabilidade\n                bebeu até a embriaguez                              (art. 28, II). Pela actio libera\n                completa e matou um                                 in causa, vale o momento\n                desafeto                                            em que ele decidiu beber,\n                                                                    livre e consciente\n\n   12           Cláudia, estrangeira,        C: isenta de pena      Erro de proibição inevitável\n                cultivou em casa uma                                (art. 21) exclui a\n                planta legal no país dela,                          culpabilidade\n                sem poder saber da\n                proibição no Brasil\n\n                                                                                              Page 26 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n   Aula         Caso                        Resposta                   Raciocínio\n\n   12           Rogério abriu o cofre sob   B: isento de pena          Coação moral irresistível\n                ameaça de morte da filha                               (art. 22) exclui a\n                                                                       culpabilidade; só o coator\n                                                                       responde\n\n   12           Servidor destruiu           B (gabarito dos slides):   Obediência hierárquica a\n                documentos por ordem        subordinado isento,        ordem não manifestamente\n                escrita do superior         responde só o superior     ilegal. O enunciado diz\n                                                                       também que a ordem era\n                                                                       “manifestamente ilegal”, o\n                                                                       que contradiz o gabarito: se\n                                                                       ela era mesmo\n                                                                       manifestamente ilegal, os\n                                                                       dois respondem. Na prova,\n                                                                       siga o gabarito dos slides,\n                                                                       mas vale confirmar com a\n                                                                       professora\n\n   13           Alberto atirou em um        C: homicídio culposo       Descriminante putativa\n                vizinho que sacava uma                                 fática evitável (art. 20, §1º):\n                lanterna, achando que                                  culpa imprópria\n                era seu desafeto sacando\n                uma arma; o erro era\n                evitável\n\n   13           João, pescador isolado,     C: isento de pena          Ele não erra sobre os fatos\n                sabia o que fazia, mas                                 (não é erro de tipo), erra\n                acreditava que pescar no                               sobre a ilicitude: erro de\n                período de defeso era                                  proibição direto inevitável\n                lícito\n\n   14           Tiago ficou no carro        C: pedido rejeitado        Quem vigia e garante a fuga\n                vigiando e garantindo a                                é coautor funcional; a\n                fuga num assalto e pediu                               redução do art. 29, §1º, é só\n                participação de menor                                  para o partícipe\n                importância\n\n   14           Sérgio (funcionário) e      B: os dois respondem       Ser funcionário público é\n                Daniel (particular)         por peculato; a            elementar do peculato e se\n                desviaram máquinas do       reincidência de Daniel     comunica (art. 30).\n                Estado; Daniel é            não passa para Sérgio      Reincidência é\n                reincidente                                            circunstância pessoal e não\n                                                                       se comunica\n\n                                                                                               Page 27 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\nCasos das aulas 9, 10 e 11\n\n\n   Aula         Caso                            Resposta             Raciocínio\n\n   9            Mário, oficial de justiça,      Duas leituras        Sistema tradicional: o fato é\n                arromba a porta do                                   formalmente típico (violação\n                devedor e leva aparelhos                             de domicílio, furto ou\n                eletrônicos com mandado                              apropriação), mas justificado\n                judicial (questão                                    por estrito cumprimento do\n                dissertativa dos slides)                             dever legal (art. 23, III).\n                                                                     Absolvição pelo art. 386, VI, do\n                                                                     CPP. Zaffaroni: o fato é atípico\n                                                                     desde a origem, porque falta\n                                                                     antinormatividade (a lei\n                                                                     processual impõe a conduta).\n                                                                     Absolvição pelo art. 386, III, do\n                                                                     CPP\n\n   10           Bernardo atirou na perna        B: lesão corporal    Desistência voluntária\n                de Cláudio com propósito                             (“posso, mas não quero”): não\n                de matar, tinha mais balas e                         responde por tentativa de\n                desistiu                                             homicídio, só pelos atos já\n                                                                     praticados (lesão leve)\n\n   10           Gabriel furtou R$ 10 mil        A: arrependimento    Art. 16: causa obrigatória de\n                sem violência e devolveu        posterior            redução de 1/3 a 2/3, e a fração\n                tudo três semanas depois,                            depende da presteza da\n                antes da denúncia                                    reparação\n\n   10           Lucas escondeu fones na         Revisão: depende da posse     Súmula 567 do STJ: vigilância\n                mochila numa loja com                                eletrônica ou seguranças, por\n                câmeras e segurança e foi                            si só, não tornam o furto\n                detido ao passar pelos                               impossível (ineficácia relativa)\n                caixas\n\n   11           Rogério agrediu a esposa e      C: tese              ADPF 779 do STF: é proibido\n                a defesa alegou “legítima       inconstitucional     sustentar a tese no Júri, sob\n                defesa da honra”                                     pena de nulidade\n\n   11           Severino instalou cerca         Revisão: dolo/culpa   A cerca oculta e potencialmente letal pode afastar a justificante; porém, a modalidade subjetiva do resultado depende da prova e não é automaticamente dolosa.\n\n                                                                                               Page 28 of 29\n\nApostila de Direito Penal – Aulas 9 a 14\n\n   Aula         Caso                         Resposta          Raciocínio\n\n   11           Laura (cão solto, sem dono   A                 Laura: estado de necessidade\n                comandando) e Diego (cão                       (perigo natural). Diego:\n                comandado pelo dono)                           legítima defesa (o animal foi\n                mataram o animal                               usado como arma)\n\n   11           Tércio atirou em Rodrigo     B: responde por   As excludentes exigem\n                para matá-lo, sem saber      homicídio         também o elemento subjetivo\n                que Rodrigo ia matar uma                       (saber que age para se\n                criança                                        defender ou defender outro).\n                                                               O resultado salvador por\n                                                               acaso não ajuda Tércio\n\n                                                                                      Page 29 of 29","summary":"Apostila integral de Direito Penal I (29 páginas), revisada nas aulas 9 a 14: teoria do crime, tipicidade, dolo e culpa, iter criminis, tentativa, desistência, arrependimentos, crime impossível, ilicitude, culpabilidade, teoria do erro e concurso de pessoas. Inclui 31 flashcards revisados, 12 itens autorais de fixação validados e 21 questões acadêmicas N1/N2 com gabaritos e explicações conferidos. Doutrina e jurisprudência foram identificadas separadamente do texto legal.","created_at":"2026-11-13T22:31:17.560425+00:00","discipline":"Direito Penal","flashcards":[{"b":"Fato típico, ilicitude e culpabilidade. A análise costuma seguir essa ordem.","f":"Aula 9 — Quais são os três substratos do crime na teoria tripartida?"},{"b":"Conduta, resultado, nexo causal e tipicidade.","f":"Aula 9 — Quais são os elementos do fato típico apresentados na apostila?"},{"b":"Formal: adequação da conduta à descrição legal. Material: lesão relevante ao bem jurídico protegido.","f":"Aula 9 — Qual é a diferença entre tipicidade formal e material?"},{"b":"Na conduta, dentro do fato típico, e não na culpabilidade.","f":"Aula 9 — No finalismo, onde ficam dolo e culpa?"},{"b":"Mínima ofensividade; ausência de periculosidade social; reduzidíssimo grau de reprovabilidade; inexpressividade da lesão jurídica.","f":"Aula 9 — Quais são os quatro vetores da insignificância segundo o HC 84.412/SP citado na apostila?"},{"b":"Cogitação, atos preparatórios, execução, consumação e, depois, exaurimento.","f":"Aula 10 — Quais são as fases do iter criminis?"},{"b":"Não. A fase interna da cogitação é impunível.","f":"Aula 10 — A cogitação é punível?"},{"b":"O objetivo-formal: começa a execução quando o agente inicia a prática do verbo do tipo penal.","f":"Aula 10 — Qual critério de início da execução a apostila aponta como tradicionalmente majoritário?"},{"b":"Dolo de consumar; início da execução; não consumação; e interrupção por circunstâncias alheias à vontade do agente.","f":"Aula 10 — Quais são os requisitos da tentativa?"},{"b":"Aplica-se a pena do crime consumado, reduzida de 1/3 a 2/3; quanto mais próximo da consumação, menor tende a ser a redução.","f":"Aula 10 — Como funciona a redução da pena na tentativa?"},{"b":"Na desistência voluntária o agente interrompe a execução podendo continuar. No arrependimento eficaz já esgotou os meios e atua para impedir o resultado, conseguindo evitá-lo.","f":"Aula 10 — Qual é a diferença entre desistência voluntária e arrependimento eficaz?"},{"b":"Depois da consumação, nos crimes sem violência ou grave ameaça, o agente repara o dano ou restitui a coisa voluntariamente, nas condições e prazo legais, com redução da pena.","f":"Aula 10 — O que é arrependimento posterior, conforme o art. 16 do CP?"},{"b":"Quando a consumação é impossível pela ineficácia absoluta do meio ou pela impropriedade absoluta do objeto.","f":"Aula 10 — Quando ocorre crime impossível segundo a ideia central do art. 17 do CP?"},{"b":"É a contrariedade do fato típico ao ordenamento jurídico como um todo; em regra, o fato típico é inicialmente considerado ilícito, salvo causa justificante.","f":"Aula 11 — O que é ilicitude?"},{"b":"Estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito.","f":"Aula 11 — Quais são as quatro causas de exclusão da ilicitude listadas no art. 23 do CP?"},{"b":"Perigo atual (a apostila também menciona a aceitação doutrinária do iminente), não provocado voluntariamente, inevitabilidade por outro meio, proteção de direito próprio ou alheio e proporcionalidade entre os bens.","f":"Aula 11 — Quais requisitos centrais do estado de necessidade aparecem no art. 24 do CP?"},{"b":"Agressão injusta, atual ou iminente; proteção de direito próprio ou de terceiro; meios necessários usados moderadamente; e conhecimento da situação justificante.","f":"Aula 11 — Quais são os requisitos da legítima defesa?"},{"b":"É ultrapassar os limites necessários ou continuar a reação depois que a agressão cessou.","f":"Aula 11 — O que é excesso na legítima defesa?"},{"b":"Imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa.","f":"Aula 12 — Quais são os três elementos da culpabilidade na teoria normativa pura?"},{"b":"Inimputabilidade: incapacidade inteira de entender a ilicitude ou de se determinar conforme esse entendimento. Semi-imputabilidade: capacidade apenas reduzida, com possibilidade de redução da pena ou substituição por medida de segurança, nos termos legais.","f":"Aula 12 — Qual é a diferença entre inimputabilidade e semi-imputabilidade por doença mental?"},{"b":"Não. Pelo art. 27 do CP, são penalmente inimputáveis e submetidos à legislação especial (ECA).","f":"Aula 12 — Menores de 18 anos são imputáveis penalmente?"},{"b":"Não, ainda que completa, conforme a regra do art. 28 do CP apresentada na apostila.","f":"Aula 12 — A embriaguez voluntária ou culposa exclui a imputabilidade?"},{"b":"Exclui dolo e culpa, tornando o fato atípico, conforme a explicação da apostila.","f":"Aula 13 — Qual é a consequência do erro de tipo essencial inevitável?"},{"b":"Erro de tipo: falsa percepção sobre elemento do tipo, exclui o dolo. Erro de proibição: o agente conhece o que faz, mas acredita que é permitido; afeta a potencial consciência da ilicitude.","f":"Aula 13 — Qual é a diferença entre erro de tipo e erro de proibição?"},{"b":"Não afasta o dolo por si só; os efeitos variam conforme a espécie. No erro sobre a pessoa e na aberratio ictus, aplicam-se as regras próprias dos arts. 20, §3º, e 73. Na aberratio criminis (art. 74), o resultado diverso pode gerar responsabilidade culposa se houver previsão legal. O dolo geral tem tratamento doutrinário próprio.","f":"Aula 13 — O que é erro de tipo acidental?"},{"b":"O agente imagina uma situação fática que, se existisse, justificaria sua conduta. Pela teoria limitada da culpabilidade descrita na apostila, o erro inevitável isenta; o evitável pode levar à punição por culpa, se prevista.","f":"Aula 13 — O que é descriminante putativa por erro sobre situação de fato?"},{"b":"A teoria monista ou unitária, em forma temperada: todos respondem pelo mesmo crime, com pena individualizada conforme a culpabilidade.","f":"Aula 14 — Qual teoria do concurso de pessoas o Código Penal adota como regra?"},{"b":"Pluralidade de agentes e condutas; relevância causal de cada contribuição; vínculo subjetivo; e unidade de infração.","f":"Aula 14 — Quais são os quatro requisitos do concurso de pessoas apresentados na apostila?"},{"b":"Induzir é fazer nascer a ideia criminosa; instigar é reforçar uma ideia que já existia.","f":"Aula 14 — Qual a diferença entre induzir e instigar?"},{"b":"O coautor divide a execução ou exerce domínio funcional do fato; o partícipe contribui sem executar o núcleo do tipo, por auxílio material ou moral.","f":"Aula 14 — O que distingue coautor de partícipe na explicação da apostila?"},{"b":"Ajuste, determinação, instigação e auxílio não são puníveis se o crime não chega pelo menos a ser tentado.","f":"Aula 14 — O que estabelece o art. 31 do CP, conforme a apostila?"}],"sort_order":1,"updated_at":"2026-11-14T18:26:58.999739+00:00","legal_basis":[{"url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","title":"Código Penal — texto compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","title":"Constituição Federal de 1988"},{"url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm","title":"Código de Processo Penal — texto compilado"},{"url":"https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm","title":"Código de Trânsito Brasileiro — texto compilado"},{"url":"https://portal.stf.jus.br/jurisprudenciaRepercussao/tema.asp?num=169","title":"STF — Tema 169 (RE 600.817)"},{"url":"https://scon.stj.jus.br/SCON/sumstj/doc.jsp?b=SUMU&h=true&i=1&l=10&livre=%40NUM%3D%22501%22&ordenacao=-%40NUM&p=true","title":"STJ — Súmula 501"},{"url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=30&sumula=711","title":"STF — Súmula 711"},{"url":"https://scon.stj.jus.br/SCON/sumstj/toc.jsp?livre=%27567%27.num.","title":"STJ — Súmula 567"},{"url":"https://scon.stj.jus.br/SCON/recrep/toc.jsp?LREF=REPETITIVOS&tema=%27934%27","title":"STJ — Tema Repetitivo 934 (furto)"},{"url":"https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=30&sumula=610","title":"STF — Súmula 610 (latrocínio)"},{"url":"https://portal.stf.jus.br/noticias/verNoticiaDetalhe.asp?idConteudo=511556&ori=1.","title":"STF — ADPF 779 (legítima defesa da honra)"},{"url":"https://scon.stj.jus.br/SCON/pesquisar.jsp?O=JT&b=ACOR&livre=%28HC.clas.+e+%40num%3D%2220819%22%29+ou+%28HC+adj+%2220819%22%29.suce.","title":"STJ — HC 20.819/MS (coautoria funcional)"},{"url":"https://scon.stj.jus.br/SCON/sumstj/toc.jsp?livre=%40num%3D527","title":"STJ — Súmula 527 (medida de segurança)"},{"url":"https://noticias.stf.jus.br/postsnoticias/supremo-aplica-principio-da-insignificancia-penal-em-liminar-de-hc/","title":"STF — HC 84.412/SP (insignificância)"},{"url":"https://atos.cnj.jus.br/atos/detalhar/4960","title":"CNJ — Resolução 487/2023"}],"reviewed_at":"2026-11-13T23:49:59.768+00:00","reviewed_by":null,"source_note":"Fonte fornecida pelo usuário: Apostila_Direito_Penal_Aulas_9_a_14 (2).pdf (29 páginas; SHA-256 d225e0c12c7f14b682b8b8b1143ff8650f9792a150c54d2ef505226e75e0e6bb). Conteúdo didático ativo: 78.069 caracteres, 31 flashcards e 12 questões de revisão. Provas N1 e N2 importadas separadamente em board_exam_questions e revisão concluída em 14/11/2026: N2 (Prova da Shelinha direito .pdf) 12/12 itens publicados; N1 (penal prova 1.pdf) 9 itens legíveis publicados (itens 1–7, 11 e 12). O PDF N1 apresenta páginas numeradas 1, 2, 3 e 5; a página 4 não foi fornecida e os itens 8–10 não foram inventados. Gabaritos baseados nas marcações do documento e conferidos juridicamente; não há gabarito oficial independente. No item N2 10, marcação original B foi preservada e resposta técnica corrigida para D.","topic_label":"Direito Penal I — Aulas 9 a 14","contest_name":"UFAC — Bacharelado em Direito (Modular) — 2026.2","legal_review":{"status":"reviewed_and_published","exception":"N2 questão 10: marcação B no documento, resposta técnica D após revisão da Súmula 567/STJ e Tema 934/STJ.","flashcards":31,"review_date":"2026-11-14","source_pages":29,"n1_missing_page":4,"source_document":"Apostila_Direito_Penal_Aulas_9_a_14 (2).pdf","answer_key_basis":"Marcas visuais do material fornecido pelo usuário, confrontadas com legislação e jurisprudência aplicáveis; não há gabarito oficial independente.","n1_missing_items":[8,9,10],"study_quiz_items":12,"n1_questions_published":9,"n2_questions_published":12,"exam_questions_published":21},"content_status":"active","practice_review":{"law":"Código Penal","items":[{"a":true,"q":"Na teoria tripartida apresentada na apostila, crime é composto por fato típico, ilicitude e culpabilidade.","why":"Correto. A apostila usa a concepção tripartida como referência majoritária e organiza a análise nesses três substratos.","origin":"doctrinal_content_crosschecked_with_course_material","article":"teoria tripartida; CP arts. 13 a 31","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":false,"q":"Pelo finalismo descrito na apostila, dolo e culpa são elementos da culpabilidade.","why":"Errado. A apostila explica que dolo e culpa foram deslocados para a conduta, dentro do fato típico.","origin":"doctrinal_content_crosschecked_with_course_material","article":"finalismo; CP arts. 13 e 18","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":false,"q":"A cogitação, por si só, é punível como tentativa quando a intenção criminosa está comprovada.","why":"Errado. A cogitação é fase interna e impunível; a tentativa exige início da execução.","origin":"doctrinal_content_crosschecked_with_course_material","article":"iter criminis; CP arts. 14 a 17","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":true,"q":"Há tentativa quando o agente inicia a execução, mas não consuma o crime por circunstâncias alheias à sua vontade.","why":"Correto. É a definição do art. 14, II, do CP reproduzida na apostila.","origin":"authored_current_official_text","article":"CP art. 14, II","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":true,"q":"Na desistência voluntária, o agente interrompe a execução mesmo podendo prosseguir; no arrependimento eficaz, impede o resultado depois de esgotar os meios executórios.","why":"Correto. Essa é a distinção prática destacada na Aula 10 e associada ao art. 15 do CP.","origin":"authored_current_official_text","article":"CP art. 15","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":false,"q":"O arrependimento posterior ocorre antes da consumação do crime.","why":"Errado. A apostila o situa depois da consumação, nos crimes sem violência ou grave ameaça, observados os requisitos do art. 16.","origin":"authored_current_official_text","article":"CP art. 16","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":true,"q":"O art. 23 do CP lista estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito.","why":"Correto. São as quatro causas de exclusão da ilicitude enumeradas na Aula 11.","origin":"authored_current_official_text","article":"CP art. 23","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":false,"q":"A legítima defesa autoriza reação contra agressão passada ou contra perigo futuro meramente incerto.","why":"Errado. A apostila exige agressão injusta atual ou iminente; agressão passada caracteriza vingança, e a futura incerta não autoriza reação.","origin":"authored_current_official_text","article":"CP art. 25","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":true,"q":"Na teoria normativa pura, a culpabilidade tem como elementos imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa.","why":"Correto. São os três elementos listados na Aula 12.","origin":"doctrinal_content_crosschecked_with_course_material","article":"teoria normativa pura; CP arts. 26 a 28","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":false,"q":"A embriaguez voluntária ou culposa exclui a culpabilidade quando completa.","why":"Errado. A apostila afirma que não exclui a imputabilidade, conforme o art. 28 do CP.","origin":"authored_current_official_text","article":"CP art. 28, II","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":true,"q":"O erro de tipo essencial sempre exclui o dolo; se inevitável, exclui também a culpa.","why":"Correto. Essa é a distinção da Aula 13: se evitável, pode haver responsabilização culposa quando prevista.","origin":"authored_current_official_text","article":"CP art. 20","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"},{"a":false,"q":"O Código Penal adota como regra a teoria pluralista no concurso de pessoas.","why":"Errado. A apostila apresenta a teoria monista ou unitária, em forma temperada, como regra do art. 29 do CP.","origin":"doctrinal_content_crosschecked_with_course_material","article":"teoria monista; CP arts. 29 a 31","source_url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm"}],"scope":"Revisão jurídica e didática dos 12 itens autorais. Dispositivos legais confrontados com o Código Penal oficial; itens de teoria tripartida, finalismo, iter criminis, culpabilidade e teoria monista são posições doutrinárias extraídas da apostila e identificadas como tais, não texto literal da lei. Alinhamento temático com o bloco de Direito Penal do edital PC-AC 2026.","status":"reviewed","sources":[{"url":"https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm","sha256":"f4c34d0668dd477858a5a331104ed4bf3ec13dc21912123f6d59b78add0e67b2","checked_at":"2026-10-24T17:19:23.900759+00:00"}],"subject":"Direito Penal","version":1,"checked_at":"2026-11-13T23:49:59.768Z","topic_label":"Direito Penal I — Aulas 9 a 14","material_slug":"ufac-2026-direito-penal-i-aulas-9-14","syllabus_topic_id":"4e918aaa-9f13-4d3a-aba8-1a660b88abd9"},"syllabus_topic_order":null,"law_version_checked_at":"2026-11-13T23:49:59.768+00:00"}'::jsonb)
